"""Render selected macro tokens without assigning generated bytes physical spans.

Parameters
----------
None

Returns
-------
None
    Pure bounded source projection; callers retain selection and native evidence.
"""

from __future__ import annotations

from bisect import bisect_left, bisect_right
from dataclasses import dataclass

from .cpp_macro_expansion import _MacroToken, _macro_tokens
from .cpp_projection import SyntaxNode, _ProjectedNode, _SourceProjection


@dataclass(frozen=True)
class _TokenProjection(_SourceProjection):
    """Use the preceding token for an exclusive end at a token boundary.

    Parameters
    ----------
    source, expanded, segments, starts, lines
        Original and projected bytes with the inherited interval mapping.
    masked_spans : tuple[tuple[int, int], ...], optional
        Licensed original-coordinate blanks, distinct from physical spelling.

    Returns
    -------
    None
        Keeps adjacent argument and replacement origins separate.
    """

    masked_spans: tuple[tuple[int, int], ...] = ()

    def _parser_layout(self, root: SyntaxNode) -> bytes:
        """Combine annotation padding with separately licensed activity blanks.

        Parameters
        ----------
        root : SyntaxNode
            Parsed root over this projection.

        Returns
        -------
        bytes
            Original-width layout without claiming masked bytes are spelling.
        """
        layout = bytearray(super()._parser_layout(root))
        for first, last in self.masked_spans:
            for offset in range(first, last):
                if layout[offset] not in (10, 13):
                    layout[offset] = 32
        return bytes(layout)

    def offset(self, value: int, *, end: bool = False) -> int:
        """Map a token boundary without borrowing the next token's origin.

        Parameters
        ----------
        value : int
            Projected byte offset.
        end : bool, optional
            Whether the offset is an exclusive end.

        Returns
        -------
        int
            Original physical offset or generated token anchor.
        """
        index = (bisect_left if end else bisect_right)(self.starts, value) - 1
        first, last, original, original_end, replaced = self.segments[max(0, index)]
        if value == last:
            return original_end
        if not replaced:
            return original + value - first
        return original_end if end and value > first else original


@dataclass(frozen=True)
class MacroReplacement:
    """Pair one original invocation range with its already selected expansion.

    Parameters
    ----------
    span : tuple[int, int]
        Nonempty physical invocation range in the original translation unit.
    tokens : tuple[_MacroToken, ...]
        Fully rescanned tokens; selection and expansion precede projection.

    Returns
    -------
    None
        Immutable projection input, without inferring active macro definitions.
    """

    span: tuple[int, int]
    tokens: tuple[_MacroToken, ...]


@dataclass(frozen=True)
class ProjectedToken:
    """Distinguish a rendered token's position, anchor and physical spelling.

    Parameters
    ----------
    projected_span : tuple[int, int]
        Byte range in the generated parser buffer.
    token : _MacroToken
        Expansion spelling and original invocation/argument anchor.
    physical_spelling_span : tuple[int, int] | None
        Original argument token range only when its spelling was not generated.
        Pasted, stringified and template tokens have no physical spelling here.

    Returns
    -------
    None
        Generated coordinates are never presented as original source offsets.
    """

    projected_span: tuple[int, int]
    token: _MacroToken
    physical_spelling_span: tuple[int, int] | None


@dataclass(frozen=True)
class SourceSegment:
    """Map an unchanged original byte interval into a projected parser buffer.

    Parameters
    ----------
    projected_start : int
        First projected byte of the copied interval.
    original_span : tuple[int, int]
        Exact original byte range copied without modification.

    Returns
    -------
    None
        Linear mapping restricted to original bytes, including lexical bodies.
    """

    projected_start: int
    original_span: tuple[int, int]


@dataclass(frozen=True)
class MacroProjection:
    """Keep original and generated buffers with separate coordinate evidence.

    Parameters
    ----------
    original : bytes
        Unmodified physical translation unit.
    source : bytes
        Parser projection with selected invocations replaced by rendered tokens.
    original_segments : tuple[SourceSegment, ...]
        Unchanged byte intervals; generated intervals are deliberately excluded.
    generated_tokens : tuple[ProjectedToken, ...]
        Rendered tokens with separate argument spelling evidence when available.
    coordinate_segments : tuple[tuple[int, int, int], ...], optional
        Projected start and original start/end for coordinate-only copied ranges,
        including licensed blanks. These do not license physical spelling.
    masked_spans : tuple[tuple[int, int], ...], optional
        Original-coordinate source intervals blanked by known activity.

    Returns
    -------
    None
        Immutable buffers and coordinate mapping, not normalized artifacts.
    """

    original: bytes
    source: bytes
    original_segments: tuple[SourceSegment, ...]
    generated_tokens: tuple[ProjectedToken, ...]
    coordinate_segments: tuple[tuple[int, int, int], ...] = ()
    masked_spans: tuple[tuple[int, int], ...] = ()

    def physical_span(
        self, start: int, end: int, *, include_arguments: bool = False
    ) -> tuple[int, int] | None:
        """Map a nonempty projected range only if every byte was copied unchanged.

        Parameters
        ----------
        start, end : int
            Inclusive start and exclusive end in the projected buffer.
        include_arguments : bool, optional
            Also accept unchanged argument token spelling when explicitly requested.

        Returns
        -------
        tuple[int, int] | None
            Original physical range, or None for invalid or generated intervals.
        """
        if not 0 <= start < end <= len(self.source):
            return None
        for segment in self.original_segments:
            first, last = segment.original_span
            projected_end = segment.projected_start + last - first
            if segment.projected_start <= start < end <= projected_end:
                shift = first - segment.projected_start
                return start + shift, end + shift
        for token in self.generated_tokens if include_arguments else ():
            first, last = token.projected_span
            if (
                token.physical_spelling_span is not None
                and first <= start < end <= last
            ):
                shift = token.physical_spelling_span[0] - first
                return start + shift, end + shift
        return None

    def syntax_tree(self, root: SyntaxNode) -> _ProjectedNode:
        """Map syntax to original bytes while preserving argument-token positions.

        Parameters
        ----------
        root : SyntaxNode
            Syntax tree over this projection, including prior syntax adapters.

        Returns
        -------
        _ProjectedNode
            Tree with physical argument spelling and explicit replacement anchors.
        """
        coordinates = self.coordinate_segments or tuple(
            (s.projected_start, *s.original_span) for s in self.original_segments
        )
        intervals = [(start, start + b - a, a, b, False) for start, a, b in coordinates]
        intervals.extend(
            (
                *t.projected_span,
                t.token.start,
                t.token.end,
                t.physical_spelling_span is None,
            )
            for t in self.generated_tokens
        )
        intervals.sort()
        segments = []
        cursor = 0
        previous_end = 0
        for first, last, a, b, replaced in intervals:
            if cursor < first:
                segments.append((cursor, first, previous_end, a, True))
            segments.append((first, last, a, b, replaced))
            cursor, previous_end = last, b
        if cursor < len(self.source):
            segments.append(
                (cursor, len(self.source), previous_end, len(self.original), True)
            )
        mapping = _TokenProjection(
            self.original,
            self.source,
            tuple(segments),
            tuple(s[0] for s in segments),
            (0, *(i + 1 for i, byte in enumerate(self.original) if byte == 10)),
            self.masked_spans,
        )
        return mapping.tree(root)


def _render_macro_tokens(
    tokens: tuple[_MacroToken, ...],
) -> tuple[bytes, tuple[tuple[int, int], ...]]:
    """Render tokens while preserving whitespace and preventing lexical merging.

    Parameters
    ----------
    tokens : tuple[_MacroToken, ...]
        Expanded preprocessing tokens, with empty placemarkers already removed.

    Returns
    -------
    tuple[bytes, tuple[tuple[int, int], ...]]
        Rendered bytes and the exact range of each token in that buffer.

    Raises
    ------
    ValueError
        If token spellings are invalid or token/output bounds are exceeded.
    """
    if len(tokens) > 32768:
        raise ValueError("macro projection token limit exceeded")
    output = bytearray()
    spans: list[tuple[int, int]] = []
    adjacent: list[bytes] = []
    for token in tokens:
        if tuple(item.spelling for item in _macro_tokens(token.spelling)) != (
            token.spelling,
        ):
            raise ValueError("invalid projected token spelling")
        separator = token.space_before
        if adjacent and not separator:
            expected = (*adjacent[-2:], token.spelling)
            try:
                actual = tuple(
                    item.spelling for item in _macro_tokens(b"".join(expected))
                )
                separator = actual != expected
            except ValueError:
                separator = True
        if separator and output:
            output.extend(b" ")
            adjacent = []
        start = len(output)
        output.extend(token.spelling)
        spans.append((start, len(output)))
        adjacent.append(token.spelling)
        if len(output) > 262144:
            raise ValueError("macro projection replacement byte limit exceeded")
    rendered = bytes(output)
    if tuple(item.spelling for item in _macro_tokens(rendered)) != tuple(
        token.spelling for token in tokens
    ):
        raise ValueError("macro projection changed preprocessing tokens")
    return rendered, tuple(spans)


def project_macro_replacements(
    source: bytes, replacements: tuple[MacroReplacement, ...]
) -> MacroProjection:
    """Project bounded nonoverlapping declaration invocations and map body bytes.

    Parameters
    ----------
    source : bytes
        Exact original translation unit.
    replacements : tuple[MacroReplacement, ...]
        Already selected complete declaration invocations in physical order.
        Boundary padding isolates replacement tokens from surrounding source.

    Returns
    -------
    MacroProjection
        Parser bytes, unchanged physical segments and separate generated tokens.

    Raises
    ------
    ValueError
        If bounds, invocation order, anchors or argument spelling evidence fail.
    """
    if len(source) > 8 * 1024 * 1024 or len(replacements) > 256:
        raise ValueError("macro projection source or invocation limit exceeded")
    output = bytearray()
    segments: list[SourceSegment] = []
    projected: list[ProjectedToken] = []
    cursor = 0
    for replacement in replacements:
        start, end = replacement.span
        if not cursor <= start < end <= len(source):
            raise ValueError("invalid or overlapping macro invocation span")
        rendered, spans = _render_macro_tokens(replacement.tokens)
        if cursor < start:
            segments.append(SourceSegment(len(output), (cursor, start)))
            output.extend(source[cursor:start])
        output.extend(b" ")
        base = len(output)
        output.extend(rendered)
        output.extend(b" ")
        for token, (first, last) in zip(replacement.tokens, spans, strict=True):
            if not start <= token.start < token.end <= end:
                raise ValueError("macro token anchor escapes original invocation")
            physical = None
            if token.argument and not token.synthetic:
                original_tokens = _macro_tokens(source[token.start : token.end])
                if tuple(item.spelling for item in original_tokens) != (
                    token.spelling,
                ):
                    raise ValueError(
                        "macro argument spelling does not match original bytes"
                    )
                physical = (token.start, token.end)
            projected.append(
                ProjectedToken((base + first, base + last), token, physical)
            )
        cursor = end
        if len(output) > 8 * 1024 * 1024:
            raise ValueError("macro projection output byte limit exceeded")
    if cursor < len(source):
        segments.append(SourceSegment(len(output), (cursor, len(source))))
        output.extend(source[cursor:])
    if len(output) > 8 * 1024 * 1024:
        raise ValueError("macro projection output byte limit exceeded")
    return MacroProjection(source, bytes(output), tuple(segments), tuple(projected))
